    text: "Я обратилась к Кравченко Д.В. в середине ноября 2012 г. с сильной болью в области правого сустава. Дмитрий Валерьевич быстро поставил диагноз и начал лечение. Для меня была изготовлена специальная дистракционная каппа, которую я должна была носить не снимая в течение трех недель. Одновременно с этим в жевательные и височные мышцы мне был закачан ботокс для снятия их перенапряжения. В конце декабря 2012 г. мне была проведена малоинвазивная артроскопическая операция (артролаваж), в результате которой мне были промыты и вправлены оба сустава, и закачан специальный имплант суставной жидкости. После операции я продолжила носить каппу в течение некоторого времени. Затем начался длительный процесс ортодонтического лечения (врач Екатерина Викторовна): необходимо было дотянуть верхние и нижние зуб друг до друга, чтобы они встали в соответсвии с новым расположением челюстей. Для меня была изготовлена специальная жесткая пластинка, которая регулировала высоту и расположения челюстей относительно друг друга и не давала им опуститься, пока проходило ортодонтическое лечение. Также мне поставили брекет-систему, которую я носила 4 месяца. В результате мне был исправлен прикус и зубы были выставлены в соответствии с новым положением челюстей. После ортодонтического лечения мне снова был закачан ботокс в мышцы, чтобы снять их гипертонус (который образовался из-за ортодонтического лечения). Для меня была изготовлена специальная релаксационная каппа, которую я ношу только на ночь, на силовые спортивные занятия и в моменты сильного стресса. На этом мое лечение закончилось. Хочется отметить, что на протяжении всего лечения Кравченко Д.В. постоянно отвечал на мои вопросы и оказывал моральную поддержку, которая была необходима мне как пациенту, так как лечение длительное, а боли в суставе были очень сильными. Выражаю безмерную благодарность Дмитрию Валерьевичу за его терпение, труд и высокий профессионализм! Большое Вам спасибо и низкий поклон! Отдельное спасибо хочется сказать ортодонту Екатерине Викторовне за профессионализм и ответственное отношение к работе.",
