function pageHref(slug) {
  return slug === "home" ? "index.html" : `${slug}.html`;
}

function readJson(slug) {
  return JSON.parse(fs.readFileSync(path.join(pagesRoot, `${slug}.json`), "utf8"));
}

function escapeHtml(value = "") {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function capitalizeFirst(value = "") {
  const text = String(value).trim();
  if (!text) return "";
  return text.charAt(0).toLocaleUpperCase("ru-RU") + text.slice(1);
}

function cleanHeroLead(value = "") {
  return String(value)
    .replace(/\s*Московская область,\s*Одинцово\.?/gi, "")
    .replace(/\s*✔\s*Бесплатная консультация.*$/i, "")
    .replace(/\s*☎.*$/i, "")
    .replace(/\s*Бесплатная консультация\s*$/i, "")
    .replace(/\s{2,}/g, " ")
    .trim();
}

function normalizeConsultationClaims(html = "") {
  return String(html)
    .replaceAll("✔ Бесплатная консультация", "✔ Консультация")
    .replaceAll("Бесплатная консультация · первичный разбор обращения", "Консультация · первичный разбор обращения")
    .replaceAll('<span class="font-semibold text-ink">Бесплатная консультация</span><span class="hidden sm:inline text-ink/55"> · первичный разбор обращения</span>', '<span class="font-semibold text-ink">Консультация</span><span class="hidden sm:inline text-ink/55"> · первичный разбор обращения</span>')
    .replaceAll('<span class="truncate">Бесплатная консультация</span>', '<span class="truncate">Записаться на консультацию</span>')
    .replaceAll('<h3 class="font-display text-2xl font-bold">Бесплатная консультация</h3>', '<h3 class="font-display text-2xl font-bold">Консультация</h3>')
    .replaceAll("Первая консультация бесплатная.<br>Перезвоним в течение рабочего дня.", "Оставьте заявку на консультацию.<br>Перезвоним в течение рабочего дня.")
    .replaceAll("Бесплатная консультация.", "Консультация.")
    .replaceAll("Запишитесь на бесплатную консультацию", "Запишитесь на консультацию")
    .replaceAll("Записаться на бесплатную консультацию", "Записаться на консультацию");
}

function phpFormHiddenFields(formType, indent = "        ") {
  return `<input type="hidden" name="form_type" value="${formType}">
${indent}<p class="hidden" aria-hidden="true">
${indent}  <label>РќРµ Р·Р°РїРѕР»РЅСЏР№С‚Рµ СЌС‚Рѕ РїРѕР»Рµ <input type="text" name="website" tabindex="-1" autocomplete="off"></label>
${indent}</p>`;
}

function preparePhpForms(html = "") {
  return String(html)
    .replace(
      /<form id="bookForm" class="([^"]+)">/,
      `<form id="bookForm" method="POST" action="/send-form.php" class="$1">
        ${phpFormHiddenFields("book")}`
    )
    .replace(
      /<select name="service" class="([^"]+)">\s*<option class="bg-ink">/,
      `<select name="service" required class="$1">
            <option value="" disabled selected class="bg-ink">`
    )
    .replace(
      /<textarea name="comment" rows="2" class="([^"]+)" placeholder="([^"]+)"><\/textarea>/,
      `<textarea name="comment" rows="2" required class="$1" placeholder="$2"></textarea>`
    )
    .replace(
      /<form id="exoForm" class="([^"]+)">/,
      `<form id="exoForm" method="POST" action="/send-form.php" class="$1">
        ${phpFormHiddenFields("exo")}`
    )
    .replace(
      /<textarea name="comment" rows="3" class="([^"]+)" placeholder="([^"]+)"><\/textarea>/g,
      `<textarea name="comment" rows="3" required class="$1" placeholder="$2"></textarea>`
    )
    .replace(
      /<script>\s*function bind\(formId, msgId\)\{[\s\S]*?bind\('bookForm','bookSuccess'\);\s*<\/script>\s*/g,
      ""
    )
    .replace(
      /<script>\s*var f = document\.getElementById\('exoForm'\);[\s\S]*?<\/script>\s*/g,
      ""
    )
    .replace(/\n\s*<p id="bookSuccess"[\s\S]*?<\/p>/g, "")
    .replace(/\n\s*<p id="exoSuccess"[\s\S]*?<\/p>/g, "");
}

