function removeLegacyTracking(html) {
  return html
    .replace(/\n?<meta name="google-site-verification" content="[^"]*"\s*\/?>/gi, "")
    .replace(/\n?<meta name="yandex-verification" content="[^"]*"\s*\/?>/gi, "")
    .replace(/\n?<!-- Yandex\.Metrika counter -->[\s\S]*?<!-- \/Yandex\.Metrika counter -->/gi, "")
    .replace(/\n?<script\b[^>]*>[\s\S]*?mc\.yandex\.ru\/metrika\/tag\.js[\s\S]*?<\/script>/gi, "")
    .replace(/\n?<noscript>\s*<div>\s*<img src="https:\/\/mc\.yandex\.ru\/watch\/72010240"[\s\S]*?<\/div>\s*<\/noscript>/gi, "")
    .replace(/\n?<!-- Google Tag Manager -->[\s\S]*?<!-- End Google Tag Manager -->/gi, "")
    .replace(/\n?<script\b[^>]*>[\s\S]*?googletagmanager\.com\/gtm\.js\?id=[\s\S]*?GTM-K7LGHNZ[\s\S]*?<\/script>/gi, "")
    .replace(/\n?<!-- Google Tag Manager \(noscript\) -->[\s\S]*?<!-- End Google Tag Manager \(noscript\) -->/gi, "")
    .replace(/\n?<noscript>\s*<iframe src="https:\/\/www\.googletagmanager\.com\/ns\.html\?id=GTM-K7LGHNZ"[\s\S]*?<\/iframe>\s*<\/noscript>/gi, "")
    .replace(/\n?<script\b[^>]*\bsrc="https:\/\/www\.googletagmanager\.com\/gtag\/js\?id=UA-189103323-1"[^>]*><\/script>/gi, "")
    .replace(/\n?<script\b[^>]*>[\s\S]*?gtag\(\s*['"]config['"]\s*,\s*['"]UA-189103323-1['"][\s\S]*?<\/script>/gi, "")
    .replace(/\n?<script\b[^>]*>[\s\S]*?tilda-stat-1\.0\.min\.js[\s\S]*?<\/script>/gi, "");
}

function applyTrackingIntegrations(html) {
  const headBlocks = `${searchVerificationTags}\n${yandexMetrikaHead}\n${googleTagManagerHead}`;
  const bodyBlocks = `${yandexMetrikaNoScript}\n${googleTagManagerNoScript}`;
  return removeLegacyTracking(html)
    .replace("</head>", `${headBlocks}\n</head>`)
    .replace(/(<body\b[^>]*>\s*)/i, `$1${bodyBlocks}\n`);
}

function normalizeContactDetails(value = "") {
  return String(value || "")
    .replace(/tel:\+?7?9099574107/gi, contactTelHref)
    .replace(/https?:\/\/wa\.me\/\+?7?9099574107/gi, contactWhatsAppUrl)
    .replace(/https?:\/\/wa\.me\/\+?79099574107/gi, contactWhatsAppUrl)
    .replace(/\+?\s*7\s*\(?\s*909\s*\)?\s*957[-\s]?41[-\s]?07/g, contactPhoneText)
    .replace(/\+?\s*7\s*\(?\s*909\s*\)?\s*957[-\s]?4107/g, contactPhoneText)
    .replace(/79099574107/g, contactPhonePlain)
    .replace(/\+7\s+926\s+332[-\s]?93[-\s]?69/g, contactPhoneText)
    .replace(/143009,\s*Московская обл\.,\s*г\.\s*Одинцово,<br>\s*Северная улица,\s*14А/gi, primaryAddressHtml)
    .replace(/143009,\s*г\.\s*Одинцово,\s*Московской обл\.,\s*Северная улица\s*14А/gi, primaryAddress)
    .replace(/143009,\s*(?:Московская обл\.,\s*)?г\.\s*Одинцово,?\s*(?:Московской обл\.,\s*)?(?:Северная улица|Северная ул\.|ул\.\s*Северная),?\s*14А/gi, primaryAddress)
    .replace(/г\.\s*Одинцово,\s*Московской обл\.,<br>\s*Красногорское ш\.,\s*д\.\s*17<br>\s*\(Территория Клинической Больницы №123\)/g, primaryAddressWithLandmarkHtml)
    .replace(/г\.\s*Одинцово,\s*Московской обл\.,\s*Красногорское ш\.,\s*д\.\s*17\s*\(Территория Клинической Больницы №123\)/g, primaryAddressWithLandmark)
    .replace(/г\.\s*Одинцово,\s*Московской обл\.,\s*Красногорское ш\.,\s*д\.\s*17/g, primaryAddress);
}

function renderStructuredData({ title, description, canonical, image, page }) {
  const pageName = title.replace(/\s*\|\s*.*$/, "");
  const graph = [
    {
      "@type": ["Organization", "MedicalBusiness"],
      "@id": `${productionBaseUrl}/#organization`,
      name: "Center of Surgery",
      url: productionBaseUrl,
      logo: `${productionBaseUrl}/logo.png`,
      image,
      telephone: contactPhoneText,
      email: "surgery79@mail.ru",
      address: {
        "@type": "PostalAddress",
        addressCountry: "RU",
        addressRegion: "Московская область",
        addressLocality: "Одинцово",
        streetAddress: "Красногорское ш., д. 17",
      },
    },
    {
      "@type": "WebPage",
      "@id": `${canonical}#webpage`,
      url: canonical,
      name: title,
      description,
      isPartOf: {
        "@id": `${productionBaseUrl}/#website`,
      },
      publisher: {
        "@id": `${productionBaseUrl}/#organization`,
      },
    },
    {
      "@type": "BreadcrumbList",
      itemListElement: [
        {
          "@type": "ListItem",
          position: 1,
          name: "Главная",
          item: `${productionBaseUrl}/`,
        },
        {
          "@type": "ListItem",
          position: 2,
          name: pageName,
          item: canonical,
        },
      ],
    },
  ];

  if (page?.slug === "trofimov" || page?.slug === "kravchenko") {
    graph.push({
      "@type": "Person",
      "@id": `${canonical}#person`,
      name: pageName,
      url: canonical,
      image,
      worksFor: {
        "@id": `${productionBaseUrl}/#organization`,
      },
    });
  }

  return `<script type="application/ld+json">${JSON.stringify({ "@context": "https://schema.org", "@graph": graph })}</script>`;
}

function updateSeo(html, page, titleOverride = "") {
  const seo = page.seo || {};
  const title = (titleOverride || seo.title || "Center of Surgery").replaceAll("—", "–");
  const ogTitle = (titleOverride || seo.og?.["og:title"] || seo.title || "").replaceAll("—", "–");
  return html
    .replace(/<title>[\s\S]*?<\/title>/, `<title>${escapeHtml(title)}</title>`)
    .replace(/<meta name="description" content="[^"]*">/, `<meta name="description" content="${escapeHtml(seo.description || "")}">`)
    .replace(/<meta name="keywords" content="[^"]*">/, `<meta name="keywords" content="${escapeHtml(seo.keywords || "")}">`)
    .replace(/<link rel="canonical" href="[^"]*">/, `<link rel="canonical" href="${escapeHtml(seo.canonical || page.url || "")}">`)
    .replace(/<meta property="og:title" content="[^"]*">/, `<meta property="og:title" content="${escapeHtml(ogTitle)}">`)
    .replace(/<meta property="og:description" content="[^"]*">/, `<meta property="og:description" content="${escapeHtml(seo.og?.["og:description"] || seo.description || "")}">`);
}

function updateSeo(html, page, titleOverride = "") {
  const seo = page.seo || {};
  const title = (titleOverride || seo.title || "Center of Surgery").replaceAll("—", "–").replaceAll("вЂ”", "вЂ“");
  const ogTitle = (titleOverride || seo.og?.["og:title"] || seo.title || "").replaceAll("—", "–").replaceAll("вЂ”", "вЂ“");
  const description = normalizeContactDetails(seo.description || "");
  const canonical = productionUrl(seo.canonical || page.url || "/");
  const ogDescription = normalizeContactDetails(seo.og?.["og:description"] || description);
  const ogUrl = productionUrl(seo.og?.["og:url"] || canonical);
  const ogImage = productionAssetUrl(seo.og?.["og:image"] || "logo.png");
  let out = html
    .replace(/<title>[\s\S]*?<\/title>/, `<title>${escapeHtml(title)}</title>`)
    .replace(/<meta name="description" content="[^"]*">/, `<meta name="description" content="${escapeHtml(description)}">`)
    .replace(/<meta name="keywords" content="[^"]*">/, `<meta name="keywords" content="${escapeHtml(seo.keywords || "")}">`);

  out = setHeadTag(out, /<link rel="canonical" href="[^"]*">/, `<link rel="canonical" href="${escapeHtml(canonical)}">`);
  out = setHeadTag(out, /<meta property="og:title" content="[^"]*">/, `<meta property="og:title" content="${escapeHtml(ogTitle)}">`);
  out = setHeadTag(out, /<meta property="og:description" content="[^"]*">/, `<meta property="og:description" content="${escapeHtml(ogDescription)}">`);
  out = setHeadTag(out, /<meta property="og:type" content="[^"]*">/, `<meta property="og:type" content="website">`);
  out = setHeadTag(out, /<meta property="og:url" content="[^"]*">/, `<meta property="og:url" content="${escapeHtml(ogUrl)}">`);
  out = setHeadTag(out, /<meta property="og:image" content="[^"]*">/, `<meta property="og:image" content="${escapeHtml(ogImage)}">`);
  out = setHeadTag(out, /<meta name="twitter:card" content="[^"]*">/, `<meta name="twitter:card" content="summary_large_image">`);
  out = setHeadTag(out, /<meta name="twitter:title" content="[^"]*">/, `<meta name="twitter:title" content="${escapeHtml(ogTitle)}">`);
  out = setHeadTag(out, /<meta name="twitter:description" content="[^"]*">/, `<meta name="twitter:description" content="${escapeHtml(ogDescription)}">`);
  out = setHeadTag(out, /<meta name="twitter:image" content="[^"]*">/, `<meta name="twitter:image" content="${escapeHtml(ogImage)}">`);
  out = out.replace(/<script type="application\/ld\+json">[\s\S]*?<\/script>\n?/g, "");
  return out.replace("</head>", `${renderStructuredData({ title, description, canonical, image: ogImage, page })}\n</head>`);
}

function socialIcon(name, sizeClass = "w-4 h-4") {
  if (name === "whatsapp") {
    return `<svg class="${sizeClass}" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M17.5 14.4l-2.6-1.3c-.4-.2-.8-.1-1 .2l-.7.9c-.2.3-.5.3-.8.2-.8-.4-1.9-1-2.7-2.6-.2-.3 0-.6.2-.8l.8-.9c.2-.2.2-.6.1-.8L9.6 6.6c-.2-.4-.7-.6-1.1-.4l-1.1.5c-.5.2-.9.7-.8 1.3.2 1.2.8 3.4 2.9 5.6 2.2 2.2 4.5 2.9 5.7 3.1.6.1 1.1-.3 1.3-.8l.5-1.1c.2-.4 0-.9-.5-1.4zM12 2C6.5 2 2 6.5 2 12c0 1.8.5 3.5 1.3 5L2 22l5.1-1.3c1.5.8 3.1 1.3 4.9 1.3 5.5 0 10-4.5 10-10S17.5 2 12 2z"/></svg>`;
  }
  if (name === "max") {
    const pixelSize = sizeClass === "w-4 h-4" ? "16" : "20";
    return `<img src="max.png" alt="" class="block ${sizeClass} max-w-none object-contain" width="${pixelSize}" height="${pixelSize}" aria-hidden="true">`;
  }
  if (name === "instagram") {
    return `<svg class="${sizeClass}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="2" y="2" width="20" height="20" rx="5"/><path d="M16 11.37A4 4 0 1 1 12.63 8 4 4 0 0 1 16 11.37z"/><line x1="17.5" y1="6.5" x2="17.51" y2="6.5"/></svg>`;
  }
  return `<svg class="${sizeClass}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"/><polyline points="22,6 12,13 2,6"/></svg>`;
}

function renderSitemap(files) {
  const urls = Object.keys(files).map((name) => (name === "index.html" ? "/" : `/${name}`));
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls
    .map((url) => `  <url><loc>${productionBaseUrl}${url}</loc></url>`)
    .join("\n")}\n</urlset>\n`;
}

