function renderRecommendationList(items, options = {}) {
  const ordered = options.ordered || false;
  const columns = options.columns || "md:grid-cols-2";
  const tag = ordered ? "ol" : "ul";
  const listItems = items
    .map((item, index) => {
      const marker = ordered
        ? String(index + 1).padStart(2, "0")
        : "•";
      return `<li class="min-h-full flex gap-3 rounded-lg border border-ink/10 bg-white px-4 py-3.5 shadow-sm">
        <span class="mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center rounded-md bg-cream text-[12px] font-mono font-semibold text-indigo2">${marker}</span>
        <span class="text-[15px] sm:text-[16px] leading-relaxed text-ink/75">${escapeHtml(item)}</span>
      </li>`;
    })
    .join("\n");
  return `<${tag} class="grid ${columns} gap-2.5 sm:gap-3">
    ${listItems}
  </${tag}>`;
}

function renderRecommendationSection(section) {
  const leadHtml = section.lead
    ? `<p class="mt-2 max-w-3xl text-[15px] sm:text-[16px] leading-relaxed text-ink/60">${escapeHtml(section.lead)}</p>`
    : "";
  const paragraphsHtml = section.paragraphs?.length
    ? `<div class="mt-4 space-y-3 text-[15px] sm:text-[16px] leading-relaxed text-ink/70">
        ${section.paragraphs.map((paragraph) => `<p>${escapeHtml(paragraph)}</p>`).join("\n")}
      </div>`
    : "";
  const listHtml = section.items?.length
    ? `<div class="mt-5">${renderRecommendationList(section.items, {
        columns: section.items.length > 8 ? "sm:grid-cols-2 lg:grid-cols-3" : "md:grid-cols-2",
      })}</div>`
    : "";
  const emphasisClass = section.emphasis ? "border-l-4 border-pink2 pl-5" : "";
  const noteHtml = section.note
    ? `<p class="mt-4 inline-flex rounded-lg bg-cream px-4 py-3 text-[15px] sm:text-[16px] font-semibold text-ink">${escapeHtml(section.note)}</p>`
    : "";
  const bodyHtml = [leadHtml, paragraphsHtml, listHtml, noteHtml].filter(Boolean).join("\n");
  return `<section class="${emphasisClass}">
    <div class="text-[12px] uppercase tracking-[0.16em] text-indigo2 font-semibold">Памятка</div>
    <h2 class="mt-2 font-display text-[25px] sm:text-[32px] lg:text-[38px] leading-tight font-bold">${escapeHtml(section.title)}</h2>
${bodyHtml}
  </section>`;
}

function renderRecommendationContent(slug) {
  if (slug === "analyzes") {
    return `<section class="py-12 sm:py-14 lg:py-20 bg-white border-y border-ink/5">
  <div class="max-w-[1180px] mx-auto px-5 lg:px-10">
    <div class="max-w-3xl">
      <div class="text-[12px] uppercase tracking-[0.16em] text-indigo2 font-semibold">Перечень</div>
      <h2 class="mt-2 font-display text-[28px] sm:text-[36px] lg:text-[44px] leading-tight font-bold">Перечень анализов</h2>
    </div>
    <div class="mt-8">
      ${renderRecommendationList(analyzesItems, { ordered: true, columns: "md:grid-cols-2" })}
    </div>
  </div>
</section>

<section class="py-12 sm:py-14 lg:py-20 bg-cream">
  <div class="max-w-[900px] mx-auto px-5 lg:px-10">
    <div class="text-[12px] uppercase tracking-[0.16em] text-pink2 font-semibold">После операции</div>
    <h2 class="mt-2 font-display text-[28px] sm:text-[36px] lg:text-[44px] leading-tight font-bold">Рекомендации после оперативного вмешательства</h2>
    <div class="mt-6 space-y-4 text-[16px] sm:text-[17px] leading-relaxed text-ink/70">
      ${analyzesRecommendationParagraphs.map((paragraph) => `<p>${escapeHtml(paragraph)}</p>`).join("\n")}
    </div>
  </div>
</section>`;
  }

  return `<section class="py-12 sm:py-14 lg:py-20 bg-white border-y border-ink/5">
  <div class="max-w-[1180px] mx-auto px-5 lg:px-10">
    <div class="space-y-12 sm:space-y-14">
      ${oralHygieneSections.map(renderRecommendationSection).join("\n")}
    </div>
  </div>
</section>`;
}

